-- Точная исходная копия всех версий well, включая дату, hashdiff и аудит.
SELECT count(*) AS n FROM ((SELECT well_hk,link_hk,event_id,entity_version,op,event_time,load_dts,record_source,hashdiff,well_name,valid_from,status FROM {{source:oil_dds__sat_well}} EXCEPT ALL SELECT well_hk,link_hk,event_id,entity_version,op,event_time,load_dts,record_source,hashdiff,well_name,valid_from,status FROM {{target:oil_dds__sat_well}}) UNION ALL (SELECT well_hk,link_hk,event_id,entity_version,op,event_time,load_dts,record_source,hashdiff,well_name,valid_from,status FROM {{target:oil_dds__sat_well}} EXCEPT ALL SELECT well_hk,link_hk,event_id,entity_version,op,event_time,load_dts,record_source,hashdiff,well_name,valid_from,status FROM {{source:oil_dds__sat_well}})) q;
